    with open('c:/git_repo/TKprof_book/books/two_cities/json/book3_ch_15.json', 'r', encoding='utf-8') as f:
        data = json.load(f)
    
    for item in data:
        tag = item['tag']
        if tag in translations:
            item['ko'] = translations[tag]['ko']
            item['en'] = translations[tag]['en']
            
    with open('c:/git_repo/TKprof_book/books/two_cities/json/book3_ch_15.json', 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)

